def audit_and_backfill_payment_contexts(apps, schema_editor):
    Pago = apps.get_model('gestion', 'Pago')
    alias = schema_editor.connection.alias
    payments = Pago.objects.using(alias)
    incompatible = {
        'turno_only': payments.filter(
            orden__isnull=True,
            turno__isnull=False,
        ).count(),
        'both_order_and_turno': payments.filter(
            orden__isnull=False,
            turno__isnull=False,
        ).count(),
        'orphan': payments.filter(
            orden__isnull=True,
            turno__isnull=True,
        ).count(),
    }
    if any(incompatible.values()):
        raise RuntimeError(
            'BH-058 B2 abortado: existen Pagos legacy sin contexto '
            f'OrdenCompra inequívoco: {incompatible}. Deben conciliarse '
            'manualmente; la migración no inventa PaymentIntents.'
        )
    for payment_id in payments.values_list('pk', flat=True).iterator():
        payments.filter(pk=payment_id).update(public_id=uuid.uuid4())


def seed_payment_role_defaults(apps, schema_editor):
    Group = apps.get_model('auth', 'Group')
    Permission = apps.get_model('auth', 'Permission')
    alias = schema_editor.connection.alias

    def permission(codename):
        return Permission.objects.using(alias).get(
            content_type__app_label='gestion',
            codename=codename,
        )

    register_payment = permission('register_payment')
    confirm_deposit = permission('confirm_deposit')
    view_financial_reports = permission('view_financial_reports')

    employee = Group.objects.using(alias).get(name='EMPLEADO')
    employee.permissions.add(register_payment)
    employee.permissions.remove(confirm_deposit)

    professional = Group.objects.using(alias).get(name='PROFESIONAL')
    professional.permissions.remove(register_payment, confirm_deposit)

    administrator = Group.objects.using(alias).get(name='ADMINISTRADOR')
    administrator.permissions.add(
        register_payment,
        confirm_deposit,
        view_financial_reports,
    )


